<?php
declare(strict_types=1);
namespace BSPMuseum;
require_once __DIR__.'/legacy.php';
const BASE='https://beyondspacetime.org';
const KINDS=['time'=>'Universal time and clock observations','design'=>'Experiment designs','module'=>'Exhibits','foundation'=>'Foundations','evidence'=>'Evidence records','gate'=>'Validation gates','experiment'=>'Experiments','investigation'=>'Investigations','comparison'=>'Model comparisons','timeline'=>'Research history','lesson'=>'Localized lessons','glossary'=>'Glossary','visualization'=>'Visualizations'];
function h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function j(mixed $v):string{return json_encode($v,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT|JSON_THROW_ON_ERROR);}
function catalog():array{static $c;return $c??=json_decode(file_get_contents(dirname(__DIR__).'/catalog.json'),true,512,JSON_THROW_ON_ERROR);}
function filters(array $input):array{
 $f=[];foreach(['q','kind','lang','page'] as $key){$v=$input[$key]??'';if(!is_string($v)||strlen($v)>160||!preg_match('//u',$v)||preg_match('/[\x00-\x1f\x7f]/',$v))throw new \InvalidArgumentException('Invalid '.$key);$f[$key]=trim($v);}
 if($f['kind']!==''&&!isset(KINDS[$f['kind']]))throw new \InvalidArgumentException('Unknown record type');if(!in_array($f['lang'],['','en','es','fr'],true))throw new \InvalidArgumentException('Unknown language');if($f['page']!==''&&(!ctype_digit($f['page'])||(int)$f['page']<1||(int)$f['page']>1000))throw new \InvalidArgumentException('Invalid page');$f['page']=(int)($f['page']?:1);return $f;
}
function matches(array $f):array{$terms=preg_split('/\s+/u',$f['q'],-1,PREG_SPLIT_NO_EMPTY);$rank=[];foreach(catalog()['entries'] as $r){if($f['kind']!==''&&$f['kind']!==$r['kind']||$f['lang']!==''&&$f['lang']!==$r['language'])continue;$score=0;foreach($terms as $term){$pat='/'.preg_quote($term,'/').'/iu';$s=0;foreach(['title'=>5,'summary'=>3,'keywords'=>1,'status'=>2,'id'=>1] as $key=>$weight)if(preg_match($pat,$r[$key]))$s+=$weight;if(!$s)continue 2;$score+=$s;}$rank[]=['score'=>$score,'record'=>$r];}usort($rank,fn($a,$b)=>$b['score']<=>$a['score']?:strcmp($a['record']['id'],$b['record']['id']));return array_column($rank,'record');}
function search(array $f):array{$all=matches($f);$total=count($all);$pages=max(1,(int)ceil($total/20));$page=min($pages,$f['page']);$f['page']=$page;return ['schema'=>'beyondspacetime.museum.search.v1','version'=>'2.5.0','filters'=>$f,'total'=>$total,'pages'=>$pages,'results'=>array_slice($all,($page-1)*20,20)];}
function headers(bool $video=false,bool $noindex=false):void{header_remove('X-Powered-By');header('X-Content-Type-Options: nosniff');header('Referrer-Policy: strict-origin-when-cross-origin');header('X-Frame-Options: DENY');header('Permissions-Policy: camera=(), microphone=(), geolocation=()');header("Content-Security-Policy: default-src 'self'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; object-src 'none'; base-uri 'none'; form-action 'self'; frame-ancestors 'none'; frame-src ".($video?'https://www.youtube-nocookie.com':"'none'"));if($noindex)header('X-Robots-Tag: noindex, follow');}
function api_method():void{headers(false,true);header('Content-Type: application/json; charset=utf-8');header('Cache-Control: no-store');if(!in_array($_SERVER['REQUEST_METHOD']??'GET',['GET','HEAD'],true)){http_response_code(405);header('Allow: GET, HEAD');echo j(['error'=>'Method not allowed']);exit;}}
function method():void{if(!in_array($_SERVER['REQUEST_METHOD']??'GET',['GET','HEAD'],true)){headers();http_response_code(405);header('Allow: GET, HEAD');exit('Method not allowed');}}
function start(string $title,string $desc,string $path,bool $noindex=false,bool $video=false):void{method();headers($video,$noindex);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=h($title)?> | Beyond Spacetime</title><meta name="description" content="<?=h($desc)?>"><meta name="robots" content="<?=$noindex?'noindex, follow':'index, follow'?>"><link rel="canonical" href="<?=BASE.$path?>"><meta property="og:title" content="<?=h($title)?> | Beyond Spacetime"><meta property="og:description" content="<?=h($desc)?>"><meta property="og:type" content="website"><meta property="og:url" content="<?=BASE.$path?>"><meta property="og:image" content="<?=BASE?>/foundations/assets/banner.webp"><meta name="theme-color" content="#081423"><link rel="icon" href="/favicon.ico" type="image/x-icon"><link rel="stylesheet" href="/museum/assets/museum.css?v=2.2.0"><script src="/museum/assets/museum.js?v=2.0.0" defer></script><?php if(str_starts_with($path,'/universal-time/')):?><link rel="stylesheet" href="/universal-time/assets/time.css?v=2.4.0"><script src="/universal-time/assets/time.js?v=2.4.0" defer></script><?php endif;?><?php if(str_starts_with($path,'/knowledge-graph/')):?><link rel="stylesheet" href="/knowledge-graph/assets/graph.css?v=2.2.0"><script src="/knowledge-graph/assets/graph.js?v=2.2.0" defer></script><?php endif;?><?php if(str_starts_with($path,'/visualizations/')):?><link rel="stylesheet" href="/visualizations/assets/visual.css?v=2.2.0"><script src="/visualizations/assets/visual-core.js?v=2.2.0" defer></script><script src="/visualizations/assets/visual.js?v=2.2.0" defer></script><?php endif;?><script type="application/ld+json"><?=j(['@context'=>'https://schema.org','@graph'=>[['@type'=>'WebSite','@id'=>BASE.'/#website','name'=>'Beyond Spacetime','url'=>BASE.'/','inLanguage'=>['en','es','fr']],['@type'=>'WebPage','@id'=>BASE.$path.'#page','url'=>BASE.$path,'name'=>$title,'description'=>$desc,'inLanguage'=>'en','isPartOf'=>['@id'=>BASE.'/#website']]]])?></script></head><body><a class="skip" href="#main">Skip to content</a><header class="masthead"><div class="wrap nav"><a href="/" class="brand"><img src="/foundations/assets/compass.png" width="48" height="48" alt=""><span>BEYOND<span class="gold">SPACETIME</span><small>THE DIGITAL SCIENCE MUSEUM</small></span></a><nav aria-label="Main navigation"><a href="/museum/">Museum</a><a href="/museum/search/">Search</a><a href="/foundations/">Learn</a><a href="/visualizations/">Visualize</a><a href="/knowledge-graph/">Graph</a><a href="/experiment-design/">Design</a><a href="/universal-time/">Time</a><a href="/research/">Investigate</a><a href="/museum/guide/">Guide & API</a></nav><a class="arc" href="https://arcsecs.com/">ArcSecs ↗</a></div></header><main id="main" class="wrap"><?php }
function end():void{?><footer><div><strong>Beyond Spacetime</strong><p>Original educational companion to the ArcSecs research program. Hypotheses and conditional calculations are not independent empirical findings.</p></div><div><a href="/museum/">Museum home</a><a href="/museum/catalog.json">Machine catalog</a><a href="/museum/sitemap-index.xml">Sitemap index</a><a href="/museum/llms.txt">Machine-readable guide</a><a href="/knowledge-graph/">Semantic knowledge graph</a></div><div><a href="https://arcsecs.com/read-book/">Original book ↗</a><a href="https://arcsecs.com/read-scientific-paper/">Scientific paper ↗</a><a href="https://www.amazon.com/dp/B0HST2C7LK/">Buy the book ↗</a></div></footer></main></body></html><?php }
function search_form(array $f=[]):void{?><form class="searchform" action="/museum/search/" method="get"><div><label for="museum-query">Search the scientific library</label><input type="search" name="q" id="museum-query" maxlength="160" value="<?=h($f['q']??'')?>" placeholder="Photon, escape, time, redshift…"></div><div class="filters"><label>Record type<select name="kind"><option value="">All types</option><?php foreach(KINDS as $k=>$v):?><option value="<?=h($k)?>" <?=($f['kind']??'')===$k?'selected':''?>><?=h($v)?></option><?php endforeach;?></select></label><label>Language<select name="lang"><option value="">All languages</option><?php foreach(['en'=>'English','es'=>'Español','fr'=>'Français'] as $k=>$v):?><option value="<?=$k?>" <?=($f['lang']??'')===$k?'selected':''?>><?=h($v)?></option><?php endforeach;?></select></label><button class="button" type="submit">Search library →</button></div></form><?php }
function card(array $r):void{?><article class="result"><span class="eyebrow"><?=h(KINDS[$r['kind']])?> · <?=h(strtoupper($r['language']))?></span><h2><a href="<?=h($r['url'])?>" lang="<?=h($r['language'])?>"><?=h($r['title'])?></a></h2><p lang="<?=h($r['language'])?>"><?=h($r['summary'])?></p><?php if($r['status']):?><p class="meta"><?=h(str_replace('_',' ',$r['status']))?></p><?php endif;?><?php if($r['related']):?><details><summary><?=count($r['related'])?> related resources</summary><ul><?php foreach($r['related'] as $a):?><li><a href="<?=h($a['url'])?>"><?=h($a['label'])?></a></li><?php endforeach;?></ul></details><?php endif;?><a class="small-link" href="/knowledge-graph/record/?id=<?=h(rawurlencode($r['id']))?>">Explore relationships →</a> <?php if(str_starts_with($r['source'],'https://')):?><a class="small-link" href="<?=h($r['source'])?>">Original source ↗</a><?php endif;?></article><?php }
function home():void{start('The integrated digital science museum','Explore the twelve foundations, scientific evidence, research investigations, model comparisons, research history, three-language education and offline learning.','/museum/',false,true);$c=catalog();?><section class="hero"><div class="hero-image"><img src="/foundations/assets/banner.webp" alt="Beyond Spacetime — a cosmic exploration from ArcSecs.com" fetchpriority="high"></div><div class="hero-copy"><div><span class="eyebrow gold">INTEGRATED DIGITAL SCIENCE MUSEUM · 2.5</span><h1>Explore the universe.<br><span class="gold">Question the model.</span></h1><p class="lead">A guided journey through light, time, matter and cosmic evolution. Read the ideas, run the mathematics, and ask what independent observations could distinguish competing explanations.</p><div class="actions"><a class="button" href="/foundations/">Begin the journey →</a><a class="button secondary" href="/visualizations/">Explore visual science</a><a class="button secondary" href="/research/">Open research workspace</a></div></div><div class="hero-aside"><span class="eyebrow">THE RESEARCH NETWORK</span><h2>One library. Many ways to explore.</h2><p>The original book, scientific manuscripts and datasets remain on ArcSecs.com. This museum connects the educational modules without duplicating the publication archive.</p><a href="https://arcsecs.com/read-book/">Read the book free ↗</a><br><a href="https://www.amazon.com/dp/B0HST2C7LK/">Buy the book ↗</a></div></div></section><div class="stats"><div><strong><?=count($c['entries'])?></strong><span>Indexed learning records</span></div><div><strong><?=count($c['modules'])?></strong><span>Integrated exhibits</span></div><div><strong>15</strong><span>Shared research models</span></div><div><strong>3</strong><span>Learning languages</span></div></div><section class="section searchpanel"><span class="eyebrow">FIND A QUESTION</span><h2>Search across the museum.</h2><?php search_form();?><div class="chips"><?php foreach(['photon','escape','time','distance','bubble'] as $q):?><a href="/museum/search/?q=<?=urlencode($q)?>"><?=h($q)?></a><?php endforeach;?></div></section><section class="section"><span class="eyebrow">CONNECTED SCIENTIFIC EXHIBITS</span><h2>Choose your expedition.</h2><div class="grid"><?php foreach($c['modules'] as $i=>$m):?><article class="tile"><span class="eyebrow gold"><?=h($m['tag'])?></span><h3><a href="<?=h($m['url'])?>"><?=h($m['title'])?></a></h3><p><?=h($m['summary'])?></p><a class="small-link" href="<?=h($m['url'])?>">Enter exhibit →</a></article><?php endforeach;?></div></section><?php if(\bsp_legacy_available()):?><section class="section"><span class="eyebrow">ORIGINAL EXPLORATION CENTER</span><h2>Continue your original exploration.</h2><p>Original site source detected. These links lead to the existing root site's learning experiences.</p><div class="chips"><a href="/learn/">Guided learning</a><a href="/atlas/">Concept atlas</a><a href="/concepts/">Concept guides</a><a href="/labs/">Interactive labs</a><a href="/explore/">Explore 3D</a><a href="/agents/">Original agent interface</a></div></section><?php endif;?><section class="section"><span class="eyebrow">CONNECTED LEARNING</span><h2>Follow a question through the evidence.</h2><div class="grid paths"><?php foreach([['What happens to light?','/foundations/photon-mass/','/evidence/ledger/escape-criterion/','/research/?preset=light'],['How large and old is the cosmos?','/foundations/cosmic-age/','/evidence/workbench/anchors/','/model-comparison/?preset=age'],['How do we test a model?','/evidence/gates/','/timeline/record/review-6/','/research/protocol/']] as $p):?><article class="tile"><h3><?=h($p[0])?></h3><ol><li><a href="<?=h($p[1])?>">Start with the concept</a></li><li><a href="<?=h($p[2])?>">Examine the evidence</a></li><li><a href="<?=h($p[3])?>">Investigate further</a></li></ol></article><?php endforeach;?></div></section><section class="section video"><span class="eyebrow">FEATURED VIDEO</span><h2>Beyond Spacetime on video.</h2><div class="video-shell" id="museum-video"><img src="/foundations/assets/banner.webp" alt=""><button class="button" id="museum-play" type="button" hidden>▶ Play featured video</button><noscript><a href="https://youtu.be/b5560LP8Wx0">Watch on YouTube</a></noscript></div><p class="muted">YouTube loads only after you select Play. <a href="https://youtu.be/b5560LP8Wx0">Watch directly on YouTube ↗</a></p></section><section class="notice"><h2>Evidence before conclusions.</h2><p>Distinguish premises, restricted model results, numerical verification and independent measurements. A failed mechanism belongs in the research history. No simulation alone establishes empirical validity.</p><a href="/evidence/">Explore the evidence ledger →</a></section><?php end();}
function search_page():void{$error='';try{$f=filters($_GET);$r=search($f);}catch(\InvalidArgumentException $e){http_response_code(400);$error=$e->getMessage();$r=search(filters([]));}start('Search the scientific museum','Find foundation lessons, model experiments, scientific evidence, research history and localized terminology.','/museum/search/',true);?><section class="intro"><span class="eyebrow gold">UNIFIED DISCOVERY</span><h1>Find the science.</h1><p>Search original catalog summaries across the connected exhibits. Results are classified by source type and language; ordering is a text relevance score, not a scientific evidence ranking.</p><?php search_form($r['filters']);?></section><?php if($error):?><p role="alert" class="notice"><?=h($error)?></p><?php endif;?><p class="meta" role="status"><?=h($r['total'])?> matching records · Page <?=$r['filters']['page']?> of <?=$r['pages']?></p><div class="results"><?php foreach($r['results'] as $a)card($a);?></div><?php if(!$r['results']):?><p class="notice">No matches. Try fewer words or remove a filter.</p><?php endif;?><nav class="pagination" aria-label="Search result pages"><?php foreach(['Previous'=>-1,'Next'=>1] as $label=>$step):$p=$r['filters']['page']+$step;if($p>=1&&$p<=$r['pages']):?><a class="button secondary" href="/museum/search/?<?=h(http_build_query(array_replace($r['filters'],['page'=>$p])))?>"><?=h($label)?></a><?php endif;endforeach;?></nav><?php end();}
function guide():void{start('Museum guide and machine interface','Navigate the scientific learning network and discover the unified search API, module catalogs and original source links.','/museum/guide/');?><section class="intro"><span class="eyebrow gold">HUMAN + MACHINE INTELLIGENCE</span><h1>Discover, calculate, reproduce.</h1><p class="lead">This museum provides one discovery layer over existing, independently executable scientific modules. Search does not replace any solver or reinterpret any result.</p></section><div class="grid two"><article class="tile"><h2>Unified catalog</h2><p>Record IDs, types, languages, source links, cross-references and original catalog hashes.</p><a href="/museum/catalog.json">GET /museum/catalog.json</a></article><article class="tile"><h2>Search API</h2><p>GET, with q, kind, lang and page. Twenty records per page. Unknown filters or invalid query strings return HTTP 400.</p><a href="/museum/api/?q=escape&amp;kind=evidence">Example: escape evidence</a></article><article class="tile"><h2>Scientific execution</h2><p>The original deterministic AG-UI research workspace and its native PHP calculation API remain authoritative for execution.</p><a href="/research/protocol/">Research protocol →</a></article><article class="tile"><h2>Discovery and citations</h2><p>Search engines can discover each original canonical page through the module sitemap index. Search results are noindex; no fabricated scientific ratings.</p><a href="/museum/sitemap-index.xml">XML sitemap index</a><br><a href="/museum/llms.txt">Machine-readable guide</a><a href="/knowledge-graph/">Semantic knowledge graph</a></article></div><section class="section"><h2>Source catalogs</h2><div class="grid two"><?php foreach(catalog()['sourceCatalogs'] as $name=>$c):?><article class="tile"><h3><?=h($name)?></h3><a href="<?=h($c['url'])?>">Original structured catalog</a><p class="hash">SHA-256: <?=h($c['sha256'])?></p></article><?php endforeach;?></div></section><section class="notice"><h2>Scope and privacy</h2><p>The index reflects supplied module snapshots, not a new scientific review. The English research remains authoritative; translated lessons are educational adaptations. The search interface sends requests to this PHP host and uses no account or analytics. The offline module has its own scoped cache; the museum is not cached by it. Hosting logs may retain requests.</p></section><?php end();}
function api():void{api_method();try{echo j(search(filters($_GET)));}catch(\InvalidArgumentException $e){http_response_code(400);echo j(['error'=>$e->getMessage()]);}}
